<template><div class="tenant-card"><h3>{{ title }}</h3><el-table v-if="rows.length" :data="rows" class="mt-3"><el-table-column prop="id" label="编号" width="90"/><el-table-column prop="title" label="标题"/><el-table-column prop="status" label="状态"/><el-table-column prop="amount" label="金额"/><el-table-column prop="created_at" label="创建时间"/></el-table><div v-else class="empty-state mt-3">{{ empty }}</div></div></template><script setup>import { onMounted, ref } from 'vue'; const props=defineProps({title:String,empty:String,loader:Function}); const rows=ref([]); onMounted(async()=>{rows.value=(await props.loader()).data||[]})</script><style scoped>h3{font-size:16px;margin:0}</style>
